//! NumPy `Generator.choice(..., p=..., replace=True)` parity.
//!
//! Expected indices were produced by NumPy 2.5.4
//! (`np.random.default_rng(seed).choice(n, size, p=w, replace=True)`).

use crate::rng::Pcg64;
use crate::measures::sum_f64;

/// `Generator.random()`: one double in [0, 1) from 53 bits.
pub fn next_double(rng: &mut Pcg64) -> f64 {
    ((rng.next_u64() >> 11) as f64) * (1.0 / 9007199254740992.0)
}

/// `Generator.choice(n, size, p=weights, replace=True)`.
///
/// Weights are normalised with NumPy's `p / p.sum()`, the CDF is the
/// sequential cumulative sum divided element-wise by its last entry, and each
/// draw is `searchsorted(cdf, u, side='right')`.
///
/// The weighted *without-replacement* route is NOT ported: NumPy does not use
/// this cumsum loop for it (verified against the reference: no association
/// variant matches), and nothing in the ported pipeline asks for it.
/// `sample_surface` always draws with replacement.
pub fn choice_weighted(rng: &mut Pcg64, weights: &[f64], size: usize) -> Vec<usize> {
    if weights.is_empty() || size == 0 {
        return Vec::new();
    }
    let total = sum_f64(weights);
    if !(total > 0.0) {
        return vec![0; size];
    }
    let p: Vec<f64> = weights.iter().map(|w| w / total).collect();
    let mut cdf = Vec::with_capacity(p.len());
    let mut acc = 0.0f64;
    for w in &p {
        acc += w;
        cdf.push(acc);
    }
    let last = *cdf.last().unwrap();
    if last > 0.0 {
        for value in cdf.iter_mut() {
            *value /= last;
        }
    }
    let mut out = Vec::with_capacity(size);
    for _ in 0..size {
        let u = next_double(rng);
        out.push(searchsorted_right(&cdf, u));
    }
    out
}

/// `np.searchsorted(cdf, u, side='right')`: first index with `cdf[i] > u`.
fn searchsorted_right(cdf: &[f64], u: f64) -> usize {
    let mut lo = 0usize;
    let mut hi = cdf.len();
    while lo < hi {
        let mid = (lo + hi) / 2;
        if cdf[mid] <= u {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    lo.min(cdf.len().saturating_sub(1))
}

